-- Mod-authored Congress splash painting descriptions, fr_FR overlay.
-- Baseline in CivVAccess_CongressDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_MISSING"] = "Aucune description pour cette image."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_SPECIAL_SESSION_START_WORLD_CONGRESS"] =
    "Une assemblée en séance, vue depuis le fond de la salle par-dessus les têtes de l'assistance. À l'avant, des délégués sont assis autour d'une longue table drapée de rouge sur une estrade recouverte d'un tapis, une feuille de papier blanc posée devant chaque place. Une figure en robe blanche et coiffe blanche se tient en bout de table pour prendre la parole, un homme à la barbe sombre à ses côtés. L'assistance lui fait face depuis des rangées de chaises en bois, turbans, calots et têtes nues mêlés. D'autres spectateurs regardent depuis entre de pâles colonnes le long du mur de droite."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_FAIR"] =
    "Une immense grande roue sort par le haut du cadre à droite, ses cabines fermées suspendues à son pourtour. Sa base plonge derrière une grande arche de fer vert à rivets qui enjambe un mur pâle portant en lettres peintes FERRIS WHEEL. Des visiteurs de l'exposition traversent la large esplanade poussiéreuse en contrebas : des femmes en longues robes, des hommes en pardessus et chapeaux melons ou hauts-de-forme. De bas bâtiments d'exposition aux enseignes peintes bordent l'allée vers la gauche, où une salle à dôme blanc se dresse au loin sous un ciel bleu pâle."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_GAMES"] =
    "Les premières foulées d'une course : quatre coureurs s'arrachent du départ, têtes baissées, sur une piste sombre qui trace un arc sur le premier plan. Derrière eux, à gauche, le starter se tient dans un long manteau blanc, son pistolet levé encore fumant. Des tribunes bondées emplissent tout l'arrière-plan, la foule brossée en petites touches de couleur. Des gradins à échelles et de hauts poteaux longent la piste sur la droite, et le vert de la pelouse intérieure s'étend au-delà."
